SET search_path=vcm,pg_catalog;
CREATE TABLE campaigns(id text PRIMARY KEY,case_id text NOT NULL REFERENCES cases(id),name text NOT NULL,responsible_id text REFERENCES principals(id),protected_object_id text NOT NULL UNIQUE REFERENCES protected_objects(id),version int NOT NULL DEFAULT 1 CHECK(version>0),created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),UNIQUE(case_id,id));
CREATE TRIGGER campaign_protect BEFORE INSERT ON campaigns FOR EACH ROW EXECUTE FUNCTION protect_object('campaign');
CREATE TABLE campaign_revisions(id text PRIMARY KEY REFERENCES object_revisions(id),campaign_id text NOT NULL REFERENCES campaigns(id),version int NOT NULL CHECK(version>0),charter jsonb NOT NULL CHECK(jsonb_typeof(charter)='object'),actor_id text NOT NULL REFERENCES principals(id),UNIQUE(campaign_id,version),UNIQUE(campaign_id,id));
CREATE TRIGGER campaign_revision_register BEFORE INSERT ON campaign_revisions FOR EACH ROW EXECUTE FUNCTION register_revision('campaigns','campaign_id');
CREATE TRIGGER campaign_revision_immutable BEFORE UPDATE OR DELETE ON campaign_revisions FOR EACH ROW EXECUTE FUNCTION immutable_row();
CREATE TABLE contents(id text PRIMARY KEY,case_id text NOT NULL REFERENCES cases(id),campaign_id text,title text NOT NULL,mode text NOT NULL DEFAULT 'weekly' CHECK(mode IN('weekly','exception')),protected_object_id text NOT NULL UNIQUE REFERENCES protected_objects(id),version int NOT NULL DEFAULT 1 CHECK(version>0),created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),FOREIGN KEY(case_id,campaign_id) REFERENCES campaigns(case_id,id));
CREATE TRIGGER content_protect BEFORE INSERT ON contents FOR EACH ROW EXECUTE FUNCTION protect_object('content');
CREATE TABLE content_revisions(id text PRIMARY KEY REFERENCES object_revisions(id),content_id text NOT NULL REFERENCES contents(id),version int NOT NULL CHECK(version>0),campaign_revision_id text REFERENCES campaign_revisions(id),brief text NOT NULL,copy text NOT NULL,channel text NOT NULL,scheduled_at timestamptz,timezone text NOT NULL DEFAULT 'America/Santiago',actor_id text NOT NULL REFERENCES principals(id),UNIQUE(content_id,version),UNIQUE(content_id,id));
CREATE TRIGGER content_revision_register BEFORE INSERT ON content_revisions FOR EACH ROW EXECUTE FUNCTION register_revision('contents','content_id');
CREATE TRIGGER content_revision_immutable BEFORE UPDATE OR DELETE ON content_revisions FOR EACH ROW EXECUTE FUNCTION immutable_row();
CREATE TABLE content_assets(content_revision_id text NOT NULL REFERENCES content_revisions(id),document_id text NOT NULL REFERENCES document_references(id),PRIMARY KEY(content_revision_id,document_id));
CREATE TABLE editorial_packages(id text PRIMARY KEY,name text NOT NULL,period_starts_on date NOT NULL,protected_object_id text NOT NULL UNIQUE REFERENCES protected_objects(id),version int NOT NULL DEFAULT 1 CHECK(version>0));
CREATE TRIGGER package_protect BEFORE INSERT ON editorial_packages FOR EACH ROW EXECUTE FUNCTION protect_object('package');
CREATE TABLE package_revisions(id text PRIMARY KEY REFERENCES object_revisions(id),package_id text NOT NULL REFERENCES editorial_packages(id),version int NOT NULL CHECK(version>0),actor_id text NOT NULL REFERENCES principals(id),UNIQUE(package_id,version));
CREATE TRIGGER package_revision_register BEFORE INSERT ON package_revisions FOR EACH ROW EXECUTE FUNCTION register_revision('editorial_packages','package_id');
CREATE TRIGGER package_revision_immutable BEFORE UPDATE OR DELETE ON package_revisions FOR EACH ROW EXECUTE FUNCTION immutable_row();
CREATE TABLE package_items(package_revision_id text NOT NULL REFERENCES package_revisions(id),content_id text NOT NULL,content_revision_id text NOT NULL,PRIMARY KEY(package_revision_id,content_id),FOREIGN KEY(content_id,content_revision_id) REFERENCES content_revisions(content_id,id));
CREATE TRIGGER package_items_immutable BEFORE UPDATE OR DELETE ON package_items FOR EACH ROW EXECUTE FUNCTION immutable_row();
CREATE TABLE publication_operations(id text PRIMARY KEY,content_revision_id text NOT NULL REFERENCES content_revisions(id),approval_id text NOT NULL,provider text NOT NULL,external_id text,idempotency_key text NOT NULL,status text NOT NULL DEFAULT 'prepared' CHECK(status IN('prepared','requested','confirmed','failed','ambiguous','cancelled')),requested_at timestamptz,confirmed_at timestamptz,result jsonb,FOREIGN KEY(content_revision_id,approval_id) REFERENCES approval_records(revision_id,id),UNIQUE(provider,idempotency_key),CHECK(status<>'confirmed' OR (external_id IS NOT NULL AND confirmed_at IS NOT NULL)));
CREATE TABLE communication_operations(id text PRIMARY KEY,object_id text NOT NULL REFERENCES protected_objects(id),destination_reference text NOT NULL,action_class text NOT NULL,mandate_id text REFERENCES operation_mandates(id),decision_outcome_id text REFERENCES decision_outcomes(id),draft text NOT NULL,status text NOT NULL DEFAULT 'prepared' CHECK(status IN('prepared','requested','confirmed','failed','ambiguous','cancelled')),provider text,external_id text,idempotency_key text NOT NULL UNIQUE,result jsonb,created_at timestamptz NOT NULL DEFAULT now(),CHECK(num_nonnulls(mandate_id,decision_outcome_id)>=1));
CREATE FUNCTION revision_unsealed() RETURNS trigger LANGUAGE plpgsql SET search_path=vcm,pg_catalog AS $$ DECLARE revision text; BEGIN revision=to_jsonb(NEW)->>TG_ARGV[0]; IF EXISTS(SELECT 1 FROM approval_records WHERE revision_id=revision) THEN RAISE EXCEPTION 'sealed revision cannot receive new children' USING ERRCODE='55000'; END IF; RETURN NEW; END $$;
CREATE TRIGGER package_items_unsealed BEFORE INSERT ON package_items FOR EACH ROW EXECUTE FUNCTION revision_unsealed('package_revision_id');
CREATE TRIGGER content_assets_unsealed BEFORE INSERT ON content_assets FOR EACH ROW EXECUTE FUNCTION revision_unsealed('content_revision_id');
CREATE TRIGGER plan_objectives_unsealed BEFORE INSERT ON plan_objectives FOR EACH ROW EXECUTE FUNCTION revision_unsealed('plan_revision_id');
